//! Parity with the TypeScript engine: every case of `engines/fixtures/situational.json`
//! (generated by `engines/fixtures/situational.ts`) must produce the same bytes.

#![allow(clippy::panic)] // a test harness reports fixture problems by panicking

use serde_json::{Map, Value};
use sipges_analytics_common::js;
use sipges_situational::run;

fn fixtures() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../fixtures/situational.json"
    );
    let text = std::fs::read_to_string(path).unwrap_or_else(|e| panic!("read {path}: {e}"));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("parse {path}: {e}"))
}

fn str_of<'a>(v: &'a Value, key: &str) -> &'a str {
    v.get(key)
        .and_then(Value::as_str)
        .unwrap_or_else(|| panic!("fixture field {key} must be a string"))
}

#[test]
fn every_case_matches_the_typescript_engine_byte_for_byte() {
    let fixtures = fixtures();
    let cases = fixtures
        .get("cases")
        .and_then(Value::as_array)
        .unwrap_or_else(|| panic!("fixture field cases must be an array"));
    assert!(cases.len() >= 25, "expected the full fixture set");
    let mut failures = Vec::new();
    for case in cases {
        let name = str_of(case, "name");
        let request: Map<String, Value> = serde_json::from_str(str_of(case, "request"))
            .unwrap_or_else(|e| panic!("{name}: request: {e}"));
        match run(&request) {
            Ok(value) => {
                let actual = js::stringify(&value);
                if actual != str_of(case, "value") {
                    failures.push(format!(
                        "{name}:\n  expected {}\n  actual   {actual}",
                        str_of(case, "value")
                    ));
                }
            }
            Err(e) => failures.push(format!("{name}: {e}")),
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

fn request(text: &str) -> Map<String, Value> {
    serde_json::from_str(text).unwrap_or_default()
}

fn code(text: &str) -> Option<&'static str> {
    run(&request(text)).err().map(|e| e.code())
}

#[test]
fn rejects_shapes_the_typescript_types_reject() {
    let ok = r#""project_id":"P","generated_at":"T""#;
    for bad in [
        r#"{"generated_at":"T"}"#.to_owned(),
        r#"{"project_id":1,"generated_at":"T"}"#.to_owned(),
        r#"{"project_id":"P"}"#.to_owned(),
        r#"{"project_id":"P","generated_at":null}"#.to_owned(),
        format!(r#"{{"records":[],{ok}}}"#),
        format!(r#"{{"records":"x",{ok}}}"#),
        format!(r#"{{"records":{{"Eventos":{{}}}},{ok}}}"#),
        format!(r#"{{"records":{{"Alertas":[1]}},{ok}}}"#),
        format!(r#"{{"records":{{"Demandas":[{{"id":1,"payload":{{}}}}]}},{ok}}}"#),
        format!(r#"{{"records":{{"Actores":[{{"id":"a","payload":[]}}]}},{ok}}}"#),
        format!(r#"{{"records":{{"Proyectos":[{{"id":"p"}}]}},{ok}}}"#),
        format!(r#"{{"records":{{"Proyectos":"x"}},{ok}}}"#),
        format!(r#"{{{ok},"tenant_label":1}}"#),
        format!(r#"{{{ok},"tenant_label":{{}}}}"#),
    ] {
        assert_eq!(code(&bad), Some("invalid_input"), "{bad}");
    }
}

#[test]
fn accepts_the_optional_fields_in_every_typed_form() {
    for good in [
        r#"{"project_id":"P","generated_at":"T"}"#,
        r#"{"records":null,"project_id":"P","generated_at":"T","tenant_label":null}"#,
        r#"{"records":{"Otro":"ignored"},"project_id":"P","generated_at":"T","tenant_label":"L"}"#,
    ] {
        assert!(run(&request(good)).is_ok(), "{good}");
    }
}
